///class particle system // based on nature of code book
class PSystem {
  ArrayList<Particle> particles;

  origin;

  PSystem(loc) {
    origin = loc.get();
    particles = new ArrayList<Particle>();
  }

  function addParticles() {
    particles.add(new Particle(origin));
  }

  function applyForce(f) {
    for (let p of particles) {
      p.applyForce(f);
    }
  }

   function applyRepeller(r) {
    for (let p of particles) {
      let force = r.repel(p);
      p.applyForce(force);
    }
  }

  function run() {
    Iterator<Particle> it =
        particles.iterator();
    while (it.hasNext()) {
      let p = it.next();
      p.run();
      p.checkEdges();
      if (p.isDead()) {
        it.remove();
      }
    }
  }
}

///class particle// based on nature of code book
class Particle {

  loc;
  vel;
  acc;

  lifespan;
  mass;

  Particle(lc) {    

    acc = new PVector(0, 0);
    vel = new PVector(0, 0);
    loc = lc.get();
    lifespan = 1000;

    mass = 1;
  }

  function applyForce(force) {
    let f = PVector.div(force, mass);
    acc.add(f);
  }


  function run() {
    update();
    display();
  }

  function update() {
    vel.add(acc);
    loc.add(vel);
    lifespan -= 2.0;
  }

  function display() {

    ellipse(loc.x, loc.y, 40, 40);
  }


  function checkEdges() {

    if (loc.x > width) {
      loc.x = width;
      vel.x *= -1;
    } else if (loc.x < 0) {
      loc.x = 0;
      vel.x *= -1;
    }

    if (loc.y > height) {
      loc.y = height;
      vel.y *= -1;
    } else if (loc.y < 0) {
      vel.y *= -1;
      loc.y = 0;
    }
  }


  isDead() {
    if (lifespan < 0.0) {
      return true;
    } else {
      return false;
    }
  }
}

